input.command:
$code = @'
const out = {};
for (const sch of ['Schematic1','Schematic2']) {
  try {
    const comps = await eda.sch_PrimitiveComponent.getAllComponents(sch);
    out[sch] = (comps||[]).map(c => ({
      designator: c.designator || c.name || c.getDesignator?.(),
      device: c.device || c.getDevice?.() || c.componentName,
      uuid: c.uuid
    }));
  } catch (e) {
    try {
      const doc = await eda.dmt_Schematic.getSchematicDocument(sch);
      out[sch + '_docKeys'] = Object.keys(doc||{});
    } catch (e2) {
      out[sch] = 'err: ' + (e.message||e) + ' | ' + (e2.message||e2);
    }
  }
}
return out;
'@; $body = @{ code = $code } | ConvertTo-Json -Compress; Invoke-RestMethod -Uri "http://localhost:49620/execute" -Method Post -ContentType "application/json" -Body $body -TimeoutSec 30 | ConvertTo-Json -Depth 8

