// try to enumerate components on both schematics via large region scan
async function dumpSchematic(label) {
  try {
    const prims = await eda.sch_Document.getPrimitivesInRegion(-50000, 50000, -50000, 50000);
    const comps = [];
    for (const p of (prims || [])) {
      let t = '';
      try { t = await p.getState_PrimitiveType?.() ?? p.getState_PrimitiveType; } catch(e) { t = 'n/a'; }
      let d = '';
      try { d = await p.getState_Designator?.() ?? p.getState_Designator; } catch(e) {}
      let dev = '';
      try { dev = await p.getState_Device?.() ?? p.getState_Device; } catch(e) {}
      let name = '';
      try { name = await p.getState_Name?.() ?? p.getState_Name; } catch(e) {}
      if (d || dev || (t && String(t).includes('Component'))) {
        comps.push({ type: String(t), designator: d, device: dev, name });
      }
    }
    return { label, totalPrims: (prims||[]).length, comps: comps.slice(0, 80) };
  } catch (e) {
    return { label, error: String(e && e.message || e) };
  }
}
const r1 = await dumpSchematic('current');
return r1;
