$code = @'
// open Board2 schematic and list components
await eda.dmt_EditorControl.openDocument('b5d0831a1e69a82d');
await new Promise(r => setTimeout(r, 1500));
const all = await eda.sch_PrimitiveComponent.getAll();
const list = [];
for (const c of (all||[])) {
  const o = {};
  for (const k of ['Designator','ComponentType','Name','Symbol']) {
    try {
      const fn = c['getState_' + k];
      if (fn) {
        const v = await fn.call(c);
        if (k === 'Symbol' && v && v.name) o[k] = v.name;
        else if (k === 'Name' && v && v.name) o[k] = v.name;
        else o[k] = v;
      }
    } catch(e) {}
  }
  list.push(o);
}
list.sort((a,b)=>String(a.Designator||'').localeCompare(String(b.Designator||''), 'en', {numeric:true}));
return { count: list.length, comps: list };
