$code = @'
const out = {};
// 1) in-EDA backup copy
try {
  const copyId = await eda.dmt_Project.copyProject();
  out.copyProject = copyId;
} catch(e) { out.copyErr = String(e && e.message || e); }

// 2) project file as base64 (first chunk)
try {
  const f = await eda.sys_FileManager.getProjectFile();
  const buf = await f.arrayBuffer();
  const bytes = new Uint8Array(buf);
  let bin = '';
  const chunk = 80000;
  for (let i = 0; i < bytes.length; i += chunk) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  const b64 = btoa(bin);
  out.b64Len = b64.length;
  out.b64Part1 = b64.slice(0, 100000);
  out.total = bytes.length;
} catch(e) { out.b64Err = String(e && e.message || e); }
return out;
