      // footprint name if object
      if (o.Footprint && typeof o.Footprint === 'object') o.Footprint = o.Footprint.name || JSON.stringify(o.Footprint).slice(0,80);
      comps.push(o);
    } catch(e) { comps.push({ id, err: String(e && e.message||e) }); }
